	"CV Studio PDF and DOCX exports are text-based.": "CV Studio के PDF और DOCX एक्सपोर्ट टेक्स्ट-आधारित होते हैं।",
	"CV Studio has no interest in your data either way.": "CV Studio को आपके डेटा में किसी भी तरह से कोई रुचि नहीं है।",
	"CV Studio has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "CV Studio में कोई मासिक प्लान नहीं है; प्रति माह की रकम सिर्फ़ सालाना कीमत ÷ 12 है। बचत की तुलना उतना ही इस्तेमाल हमारी अपनी सिंगल-यूज़ कीमत पर एक-एक करके खरीदने से की गई है। Global Pro में 300 CV जनरेशन भी शामिल हैं, जो ऊपर की बचत में नहीं गिने गए।",
	"CV Studio home": "CV Studio होम",
