	"CV Studio is currently in trial mode and is not taking real payments yet.": "CV Studio अभी ट्रायल मोड में है और अभी असली भुगतान नहीं ले रहा है।",
	"CV Studio is currently in trial mode and no real payments are taken yet.": "CV Studio अभी ट्रायल मोड में है, अभी कोई असली भुगतान नहीं लिया जा रहा है।",
	"CV Studio is currently in trial mode and no real payments are taken yet. Features and plans may change before full launch. Packages you have already bought keep the terms they were bought with.": "CV Studio अभी ट्रायल मोड में है, अभी कोई असली भुगतान नहीं लिया जा रहा है। पूरे लॉन्च से पहले फ़ीचर और प्लान बदल सकते हैं। पहले से खरीदे गए पैकेज उन्हीं शर्तों पर रहेंगे जिन पर वे खरीदे गए थे।",
	"CV Studio is currently in trial mode. No real payments are taken yet.": "CV Studio अभी ट्रायल मोड में है। अभी कोई असली भुगतान नहीं लिया जा रहा है।",
