	"Clearing your browser data, or using a different browser or device, removes or hides that saved CV. Please keep your own copy (download it).": "ब्राउज़र डेटा साफ़ करने, या दूसरा ब्राउज़र/डिवाइस इस्तेमाल करने पर सेव किया गया CV हट या छिप सकता है। अपनी कॉपी (डाउनलोड) ज़रूर रखें।",
	"Click any line on the page to edit it. The form stays in step.": "पेज की किसी भी लाइन पर क्लिक करके उसे बदलें। फ़ॉर्म साथ-साथ अपडेट होता है।",
	"Client details are auto-deleted after {days} days, or earlier on request.": "ग्राहक विवरण {days} दिन बाद, या अनुरोध पर पहले, स्वतः हटा दिए जाते हैं।",
	"Client submissions and plan records are stored on our server (hosted on Render). Encryption at rest of these records is planned as part of a database migration and is not yet complete.": "ग्राहक विवरण और प्लान रिकॉर्ड हमारे सर्वर (Render पर होस्टेड) पर रखे जाते हैं। इन रिकॉर्ड का एन्क्रिप्शन डेटाबेस माइग्रेशन के साथ योजना में है और अभी पूरा नहीं हुआ है।",
	"Client submissions: automatically deleted after {days} days, or earlier when the client or the business deletes them.": "ग्राहक विवरण: {days} दिन बाद, या ग्राहक या बिज़नेस द्वारा पहले हटाने पर, स्वतः हटा दिए जाते हैं।",
