	"Creating, editing, saving and choosing templates are free. The free download carries a watermark. Clean downloads and form fills use paid credits, as described on the Services & Plans page.": "CV बनाना, एडिट करना, सेव करना और टेम्पलेट चुनना मुफ़्त है। मुफ़्त डाउनलोड पर वॉटरमार्क होता है। क्लीन डाउनलोड और फ़ॉर्म फ़िल के लिए पेड क्रेडिट लगते हैं, जैसा Services & Plans पेज पर बताया गया है।",
	"Crop tightly around the signature. Do not sign in capital letters if the notice forbids it.": "हस्ताक्षर के चारों ओर कसकर क्रॉप करें। अगर अधिसूचना मना करे तो बड़े अक्षरों (कैपिटल) में हस्ताक्षर न करें।",
