	"Follow the employer's instructions first. If none are given, a plain single-column layout is the safest choice for online portals, while a two-column layout reads well when a person opens the PDF.": "पहले नियोक्ता के निर्देश मानें। अगर कोई निर्देश न हो, तो ऑनलाइन पोर्टल के लिए सादा एक-कॉलम लेआउट सबसे सुरक्षित है, जबकि कोई व्यक्ति PDF खोले तो दो-कॉलम लेआउट अच्छा पढ़ा जाता है।",
	"Follow the job advertisement. If it says CV, send a CV; if it says resume, send a resume.": "नौकरी के विज्ञापन का पालन करें। CV माँगा हो तो CV भेजें; रिज़्यूमे माँगा हो तो रिज़्यूमे।",
	"Fonts are loaded from Google Fonts, so Google receives a normal request from your browser.": "फ़ॉन्ट Google Fonts से लोड होते हैं, इसलिए Google को आपके ब्राउज़र से सामान्य अनुरोध मिलता है।",
	"For a minor: name, phone, nationality.": "नाबालिग के लिए: नाम, फ़ोन, राष्ट्रीयता।",
