	"Free: create, edit, save and choose templates, with no login. Download a watermarked copy free.": "मुफ़्त: CV बनाएँ, एडिट करें, सेव करें और टेम्पलेट चुनें, बिना लॉगिन। वॉटरमार्क वाली कॉपी मुफ़्त डाउनलोड करें।",
