	"How applicant tracking systems read CVs and how to make sure yours is parsed correctly.": "एप्लिकेंट ट्रैकिंग सिस्टम CV कैसे पढ़ते हैं और कैसे सुनिश्चित करें कि आपका सही से पढ़ा जाए।",
	"How do I contact you?": "आपसे संपर्क कैसे करें?",
	"How do refunds work?": "रिफंड कैसे मिलता है?",
	"How it works": "कैसे काम करता है",
	"How to choose": "कैसे चुनें",
	"How to prepare a passport-style photo and signature that portals accept.": "पासपोर्ट-स्टाइल फ़ोटो और हस्ताक्षर कैसे तैयार करें जिन्हें पोर्टल स्वीकार करें।",
	"How to write a CV as a fresher": "फ्रेशर के रूप में CV कैसे लिखें",
	"How to write a cover letter": "कवर लेटर कैसे लिखें",
	"I agree my details are shared with {biz} for form filling.": "मैं सहमत हूँ कि मेरा विवरण फ़ॉर्म भरने के लिए {biz} के साथ साझा किया जाए।",
	"I have read this notice and agree to my data being stored for this purpose. I can withdraw at any time.": "मैंने यह सूचना पढ़ ली है और इस उद्देश्य के लिए अपना डेटा संग्रहीत करने की सहमति देता/देती हूँ। मैं कभी भी सहमति वापस ले सकता/सकती हूँ।",
	Identity: "पहचान",
	"Identity, work, study, languages, and contact.": "पहचान, काम, पढ़ाई, भाषाएँ और संपर्क।",
	"If a personal data breach occurs, we will inform affected users and the Data Protection Board of India without delay, and aim to do so within 72 hours of becoming aware of it.": "डेटा उल्लंघन होने पर हम प्रभावित उपयोगकर्ताओं और डेटा संरक्षण बोर्ड को बिना देरी, 72 घंटे के भीतर सूचित करने का प्रयास करेंगे।",
	"If it is too small, the portal may reject it as unclear. Do not over-compress.": "बहुत छोटी हो तो पोर्टल उसे अस्पष्ट मानकर रद्द कर सकता है। ज़रूरत से ज़्यादा कम्प्रेस न करें।",
	"If the file is too large, reduce the dimensions or the JPG quality.": "फ़ाइल बहुत बड़ी हो तो माप या JPG क्वालिटी कम करें।",
	"If this policy changes, we will update this page and its date.": "अगर यह नीति बदलती है, तो हम यह पेज और इसकी तारीख अपडेट करेंगे।",
	"If you paid ₹20 and the PDF/DOCX does not generate, or the download fails because of a technical error on our side, you get a full refund.": "अगर आपने ₹20 दिए और PDF/DOCX नहीं बना, या हमारी तरफ़ की तकनीकी गड़बड़ी से डाउनलोड नहीं हुआ, तो आपको पूरा पैसा वापस मिलेगा।",
	"In CV Studio you can draw your signature or upload one; it is trimmed and saved as a PNG.": "CV Studio में आप हस्ताक्षर बना सकते हैं या अपलोड कर सकते हैं; उसे ट्रिम करके PNG के रूप में सेव किया जाता है।",
	"In your browser's local storage on your own device. Clearing browser data or switching device can remove it, so download a copy.": "आपके अपने डिवाइस पर ब्राउज़र के local storage में। ब्राउज़र डेटा साफ़ करने या डिवाइस बदलने पर यह हट सकता है, इसलिए कॉपी डाउनलोड कर लें।",
	"India: \"CV\" and \"resume\" are used interchangeably. Most private employers expect one or two pages.": "भारत: \"CV\" और \"रिज़्यूमे\" एक-दूसरे की जगह इस्तेमाल होते हैं। ज़्यादातर निजी नियोक्ता एक-दो पेज चाहते हैं।",
