	"It fills job application forms from your CV. A form-fill credit is used only when the fill succeeds, and is refunded if it fails. Always check the form before submitting.": "यह आपके CV से नौकरी के आवेदन फ़ॉर्म भरता है। क्रेडिट सिर्फ़ सफल फ़िल पर लगता है और असफल होने पर वापस होता है। भेजने से पहले फ़ॉर्म ज़रूर जाँचें।",
	"It is needed only to fill your forms / build your CV.": "यह केवल आपके फ़ॉर्म भरने / CV बनाने के लिए आवश्यक है।",
	"It never invents values. Anything missing is asked for and saved for next time.": "यह कभी कोई मान नहीं गढ़ता। जो छूटा है वह पूछा जाता है और अगली बार के लिए सेव होता है।",
	"Jobs matching your CV": "आपके CV से मेल खाती नौकरियाँ",
	"Keep a list of where you applied and on which date.": "कहाँ और किस तारीख को आवेदन किया, इसकी सूची रखें।",
	"Keep caste, income, disability or domicile certificates ready if you claim any category benefit.": "अगर आप किसी श्रेणी का लाभ ले रहे हैं तो जाति, आय, दिव्यांगता या निवास प्रमाणपत्र तैयार रखें।",
	"Keep copies in the exact required sizes in one folder for future applications.": "भविष्य के आवेदनों के लिए सटीक साइज़ वाली प्रतियाँ एक फ़ोल्डर में रखें।",
