	Male: "Unspecified",
	"Many CV tools charge around $24–$50 per month on monthly plans. CV Studio has no monthly plan: we sell single uses and yearly plans.": "कई CV टूल मासिक प्लान पर लगभग $24–$50 प्रति माह लेते हैं। CV Studio में कोई मासिक प्लान नहीं है: हम सिंगल-यूज़ और सालाना प्लान बेचते हैं।",
	"Many companies run CVs through software before a person reads them. Simple formatting helps it read yours correctly.": "कई कंपनियाँ किसी व्यक्ति के पढ़ने से पहले CV को सॉफ़्टवेयर से गुज़ारती हैं। सरल फ़ॉर्मेटिंग से वह आपका CV सही पढ़ता है।",
