	Native: "मातृभाषा",
	"Never invent qualifications or experience. Background checks are common.": "कभी भी योग्यता या अनुभव गढ़ें नहीं। बैकग्राउंड जाँच आम है।",
	"Next steps: tips and guides": "आगे क्या करें: सुझाव और गाइड",
	No: "नहीं",
	"No CVs yet. Start building your first CV — it only takes a few minutes.": "अभी कोई CV नहीं। अपना पहला CV बनाना शुरू करें — बस कुछ मिनट लगते हैं।",
	"No account is needed. There is no login on this site — you can use it as a guest.": "कोई अकाउंट ज़रूरी नहीं है। इस साइट पर कोई लॉगिन नहीं है — आप गेस्ट के रूप में इस्तेमाल कर सकते हैं।",
	"No active plan": "कोई सक्रिय प्लान नहीं",
	"No ad is available right now. You can still pay ₹20 or download the free watermarked PDF.": "अभी कोई विज्ञापन उपलब्ध नहीं है। आप फिर भी ₹20 दे सकते हैं या मुफ़्त वॉटरमार्क वाली PDF डाउनलोड कर सकते हैं।",
	"No applications yet. Use “Fill a form” to apply to a company.": "अभी कोई आवेदन नहीं। किसी कंपनी में आवेदन के लिए “फ़ॉर्म भरें” इस्तेमाल करें।",
	"No client details yet. Share the link above.": "अभी कोई ग्राहक विवरण नहीं। ऊपर दिया लिंक शेयर करें।",
	"No code is sent to your inbox. This button takes you straight in.": "आपके इनबॉक्स में कोई कोड नहीं आता। यही बटन आपको सीधे अंदर ले जाता है।",
	"No expiry date": "कोई समाप्ति तिथि नहीं",
	"No job history yet? A clear one-page CV built around education, projects and skills still gets shortlisted.": "अभी कोई नौकरी का अनुभव नहीं? शिक्षा, प्रोजेक्ट और कौशल पर बना साफ़ एक पेज का CV भी शॉर्टलिस्ट होता है।",
	"No login is needed — you can use CV Studio as a guest.": "कोई लॉगिन ज़रूरी नहीं — आप गेस्ट के रूप में इस्तेमाल कर सकते हैं।",
	"No refund once credits have been actively used.": "क्रेडिट इस्तेमाल हो जाने के बाद रिफंड नहीं मिलेगा।",
	"No roles yet.": "अभी कोई पद नहीं।",
	"No study yet.": "अभी कोई पढ़ाई नहीं।",
	"No verification code will be emailed; this desk has no mailbox. Enter your email and you go straight in.": "ईमेल पर कोई सत्यापन कोड नहीं आएगा; इस डेस्क का कोई मेलबॉक्स नहीं है। ईमेल लिखते ही आप अंदर चले जाएँगे।",
	"No, or the sticker number": "नहीं, या स्टिकर नंबर",
	"No. There are single-use payments and yearly plans only.": "नहीं। सिर्फ़ सिंगल-यूज़ भुगतान और सालाना प्लान हैं।",
	None: "कोई नहीं",
	"Not adding all qualifications, or entering marks in the wrong format (percentage instead of CGPA).": "सभी योग्यताएँ न जोड़ना, या अंक गलत फ़ॉर्मेट में भरना (CGPA की जगह प्रतिशत)।",
	"Not applicable": "लागू नहीं",
	"Not now": "अभी नहीं",
