	"Not yet. CV Studio is in trial mode and no real payments are taken.": "अभी नहीं। CV Studio ट्रायल मोड में है और कोई असली भुगतान नहीं लिया जा रहा है।",
	Note: "नोट",
	"Note the exact document specifications for photo, signature and certificates before you start.": "शुरू करने से पहले फ़ोटो, हस्ताक्षर और प्रमाणपत्रों के सटीक विनिर्देश नोट कर लें।",
	"Note: CV Studio is currently in trial mode. No real payments are being taken yet.": "ध्यान दें: CV Studio अभी ट्रायल मोड में है। अभी कोई असली भुगतान नहीं लिया जा रहा है।",
	Notes: "टिप्पणियाँ",
