	"Online recruitment forms are strict. One wrong date or a mismatched name can get an application rejected.": "ऑनलाइन भर्ती फ़ॉर्म सख़्त होते हैं। एक गलत तारीख या मेल न खाता नाम आवेदन रद्द करा सकता है।",
	"Only list skills you can discuss in an interview. Interviewers often test one at random.": "सिर्फ़ वही कौशल लिखें जिन पर आप इंटरव्यू में बात कर सकें। इंटरव्यूअर अक्सर किसी एक को परखते हैं।",
	"Only the fields your form needs.": "सिर्फ़ वही जानकारी जो आपका फ़ॉर्म माँगता है।",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). CV Studio has no interest in your data beyond this purpose.": "सिर्फ़ आपका CV बनाने, फ़ॉर्म भरने और प्लान उपयोग गिनने के लिए। हम आपका डेटा नहीं बेचते और आपके CV डेटा से प्रोफ़ाइलिंग नहीं करते। विज्ञापन, अगर चालू हों, केवल कंटेंट पेजों पर दिखते हैं और Google विज्ञापन कुकीज़ का उपयोग कर सकते हैं (पूरी गोपनीयता नीति देखें)। इस उद्देश्य के अलावा CV Studio की आपके डेटा में कोई रुचि नहीं है।",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data, show ads, or use it for profiling. CV Studio has no interest in your data beyond this purpose.": "केवल आपका CV बनाने और फ़ॉर्म भरने के लिए। हम डेटा नहीं बेचते, विज्ञापन नहीं दिखाते। CV Studio को इसके अलावा आपके डेटा में कोई रुचि नहीं है।",
	"Open the desk": "डेस्क खोलें",
	"Open the desk with your email": "अपने ईमेल से डेस्क खोलें",
	"Open the downloaded file once and check names, dates and contact details.": "डाउनलोड की गई फ़ाइल एक बार खोलकर नाम, तारीखें और संपर्क विवरण जाँचें।",
	"Open the file once to make sure it is the right image and not rotated.": "फ़ाइल एक बार खोलकर देखें कि सही तस्वीर है और घूमी हुई नहीं है।",
	"Opening the file…": "फ़ाइल खोली जा रही है…",
	"Opening: the role you are applying for and where you saw it.": "शुरुआत: आप किस भूमिका के लिए आवेदन कर रहे हैं और विज्ञापन कहाँ देखा।",
	"Optional photo": "वैकल्पिक फ़ोटो",
	"Optional. Germany and the Gulf often expect a photo; leave it off for the US, UK and Canada.": "वैकल्पिक। जर्मनी और खाड़ी देश अक्सर फ़ोटो माँगते हैं; अमेरिका, ब्रिटेन और कनाडा के लिए न लगाएँ।",
	"Optional. You can skip or close the ad. One free clean download per day. Paying ₹20 is always available.": "वैकल्पिक। आप विज्ञापन छोड़ या बंद कर सकते हैं। रोज़ एक मुफ़्त साफ़ डाउनलोड। ₹20 देकर अनलॉक करने का विकल्प हमेशा उपलब्ध है।",
	"Or email {email} to request deletion.": "या हटाने का अनुरोध करने के लिए {email} पर ईमेल करें।",
	"Or watch a short ad to download free": "या मुफ़्त डाउनलोड के लिए एक छोटा विज्ञापन देखें",
	"Order {id}… · {plan} {price}. These buttons ask the server to simulate an outcome. Nothing is charged, and test unlocks never count as real purchases.": "ऑर्डर {id}… · {plan} {price}। ये बटन सर्वर से एक नतीजे का सिमुलेशन करवाते हैं। कोई पैसा नहीं कटता, और टेस्ट अनलॉक कभी असली खरीद नहीं गिने जाते।",
	Ordinary: "साधारण",
	Organization: "संगठन",
	Other: "अन्य",
	"Other nationalities": "अन्य राष्ट्रीयताएँ",
	"Our hosting provider (Render) receives normal technical request data such as IP address and browser type.": "हमारा होस्टिंग प्रदाता (Render) सामान्य तकनीकी जानकारी जैसे IP पता और ब्राउज़र प्रकार प्राप्त करता है।",
	"PDF and DOCX (Word).": "PDF और DOCX (Word)।",
	"PDF text": "PDF टेक्स्ट",
	"PDF, photo, or image. The reader autofills the form on this device.": "PDF, फ़ोटो या इमेज। रीडर इसी डिवाइस पर फ़ॉर्म भरता है।",
	"PIN code": "पिन कोड",
	"Paid options remove the watermark and add form fills: Single Use ₹20 (India) or $1 (global) for one clean CV download or one form fill; Career Starter ₹1,000/year (2 profiles, 100 CV generations, 100 form fills); Global Pro $29/year (300 CV generations, 300 form fills).": "पेड विकल्प वॉटरमार्क हटाते हैं और फ़ॉर्म फ़िल देते हैं: Single Use ₹20 (भारत) या $1 (ग्लोबल) — एक क्लीन CV डाउनलोड या एक फ़ॉर्म फ़िल; Career Starter ₹1,000/साल (2 प्रोफ़ाइल, 100 CV जनरेशन, 100 फ़ॉर्म फ़िल); Global Pro $29/साल (300 CV जनरेशन, 300 फ़ॉर्म फ़िल)।",
	"Paid: clean (no watermark) downloads and form fills with single-use credits or a yearly plan.": "पेड: क्लीन (बिना वॉटरमार्क) डाउनलोड और फ़ॉर्म फ़िल, सिंगल-यूज़ क्रेडिट या सालाना प्लान से।",
	Paper: "कागज़",
	Particulars: "विवरण",
