	"Pay the fee only through the official portal, and save the payment receipt and application number.": "फ़ीस केवल आधिकारिक पोर्टल से भरें, और भुगतान रसीद व आवेदन संख्या सँभालकर रखें।",
	"Pay {price} and unlock": "{price} देकर अनलॉक करें",
	"Payment / order ID": "पेमेंट / ऑर्डर ID",
	"Payment cancelled. Nothing was charged and your CV is unchanged.": "भुगतान रद्द हुआ। कोई पैसा नहीं कटा और आपका CV वैसा ही है।",
	"Payment verified — your clean file is downloading.": "भुगतान सत्यापित — आपकी साफ़ फ़ाइल डाउनलोड हो रही है।",
	"Payments are processed by the payment provider; we do not store card numbers.": "भुगतान, पेमेंट प्रदाता द्वारा प्रोसेस होते हैं; हम कार्ड नंबर संग्रहीत नहीं करते।",
	"Per month (approx.)": "प्रति माह (लगभग)",
