	"Photo or signature in the wrong size, format or background.": "गलत साइज़, फ़ॉर्मेट या बैकग्राउंड वाली फ़ोटो या हस्ताक्षर।",
	"Pick a plan to download clean CVs and auto-fill forms.": "साफ़ CV डाउनलोड करने और फ़ॉर्म ऑटो-फ़िल करने के लिए प्लान चुनें।",
