	"Plain text": "सादा टेक्स्ट",
	Plan: "प्लान",
	"Plan & usage: an anonymous guest id, your plan key, download/form-fill counts and the company names you fill forms for.": "प्लान और उपयोग: एक गुमनाम गेस्ट ID, आपकी प्लान कुंजी, डाउनलोड/फ़ॉर्म-फ़िल की गिनती और जिन कंपनियों के फ़ॉर्म आप भरते हैं उनके नाम।",
	"Please fill your details here so we can fill your form:": "कृपया अपना विवरण यहाँ भरें ताकि हम आपका फ़ॉर्म भर सकें:",
