	"Postal code": "पिन कोड",
	"Practical tips for online recruitment forms: documents, details, fees and the final submission.": "ऑनलाइन भर्ती फ़ॉर्म के लिए व्यावहारिक सुझाव: दस्तावेज़, विवरण, फ़ीस और अंतिम सबमिशन।",
	"Practical, free guides for writing your CV and filling application forms correctly.": "CV लिखने और आवेदन फ़ॉर्म सही भरने के लिए व्यावहारिक, मुफ़्त गाइड।",
	"Prepare documents in advance": "दस्तावेज़ पहले से तैयार रखें",
	"Press Enter to add each skill.": "हर कौशल जोड़ने के लिए Enter दबाएँ।",
	Preview: "प्रीव्यू",
	"Preview PDF (watermarked)": "प्रीव्यू PDF (वॉटरमार्क वाला)",
	"Preview carries a “{mark}” watermark on every page. Use “Unlock Clean Download” for a clean file. (The watermark deters casual reuse; screenshots cannot be prevented.)": "प्रीव्यू के हर पेज पर “{mark}” वॉटरमार्क होता है। साफ़ फ़ाइल के लिए “साफ़ डाउनलोड अनलॉक करें” इस्तेमाल करें। (वॉटरमार्क आकस्मिक दुरुपयोग रोकता है; स्क्रीनशॉट रोके नहीं जा सकते।)",
