	"Sample form": "सैंपल फ़ॉर्म",
	"Save as PDF unless the employer asks for Word, and name the file with your name, for example Priya-Sharma-CV.pdf.": "जब तक नियोक्ता Word न माँगे, PDF में सेव करें और फ़ाइल का नाम अपने नाम पर रखें, जैसे Priya-Sharma-CV.pdf।",
