	"Scanned PDF": "स्कैन किया गया PDF",
	"Schengen and visa forms ask for these options. Indian passports may also carry ECNR or ECR.": "शेंगेन और वीज़ा फ़ॉर्म यही विकल्प माँगते हैं। भारतीय पासपोर्ट पर ECNR या ECR भी हो सकता है।",
