	"See the Refund Policy. In short: ₹20 single use is refunded if the download fails because of our technical error; yearly plans are refundable within 7 days if unused.": "रिफंड नीति देखें। संक्षेप में: हमारी तकनीकी गड़बड़ी से डाउनलोड न होने पर ₹20 वापस; सालाना प्लान 7 दिनों में, अगर इस्तेमाल नहीं हुआ, तो रिफंड।",
