	"Support is by email at team@formzalo.com; requests are reviewed within 2 working days.": "सहायता ईमेल से: team@formzalo.com; अनुरोधों की जाँच 2 कार्य-दिवसों में होती है।",
	"Support is by email only. We review requests within 2 working days.": "सहायता सिर्फ़ ईमेल से। हम 2 कार्य-दिवसों में अनुरोध देखते हैं।",
