	"Withdraw consent": "सहमति वापस लें",
	"Withdraw consent & delete my data": "सहमति वापस लें और मेरा डेटा हटाएँ",
	"Withdraw consent and delete all CV Studio data saved in this browser (CVs, drafts, plan key, history)? This cannot be undone.": "सहमति वापस लें और इस ब्राउज़र में सेव सारा CV Studio डेटा (CV, ड्राफ़्ट, प्लान कुंजी, इतिहास) हटाएँ? यह पूर्ववत नहीं हो सकता।",
	"Withdraw consent and delete the details you sent?": "सहमति वापस लें और भेजा गया विवरण हटाएँ?",
