	"Work history": "कार्य अनुभव",
	"Work history, education, skills and languages are shared with the CV Generator.": "कार्य अनुभव, शिक्षा, कौशल और भाषाएँ CV जनरेटर के साथ साझा हैं।",
	"Work or visit": "काम या यात्रा",
	"Write a short cover letter for each application.": "हर आवेदन के लिए छोटा कवर लेटर लिखें।",
	"Write job titles and dates clearly and in the same format throughout.": "पद और तारीखें साफ़ और पूरे CV में एक ही फ़ॉर्मेट में लिखें।",
	"Write two or three lines saying what you studied, what you are good at and the role you want.": "दो-तीन पंक्तियों में लिखें कि आपने क्या पढ़ा, आप किसमें अच्छे हैं और कौन-सी भूमिका चाहते हैं।",
