	"Yearly price": "सालाना कीमत",
	Yes: "हाँ",
	"Yes (watermarked download)": "हाँ (वॉटरमार्क वाला डाउनलोड)",
	"Yes. Creating, editing, saving and choosing templates are free, and you can download a watermarked PDF/DOCX for free. A clean download or a form fill costs ₹20 / $1 each, or you can use a yearly plan (see Services & Plans).": "हाँ। CV बनाना, एडिट करना, सेव करना और टेम्पलेट चुनना मुफ़्त है, और वॉटरमार्क वाला PDF/DOCX मुफ़्त डाउनलोड कर सकते हैं। क्लीन डाउनलोड या एक फ़ॉर्म फ़िल ₹20 / $1 का है, या आप सालाना प्लान ले सकते हैं (Services & Plans देखें)।",
	"You are responsible for checking every form before you submit it to an employer. A form-fill credit is used only when a fill succeeds, and is refunded if the fill fails.": "किसी भी फ़ॉर्म को नियोक्ता को भेजने से पहले जाँचना आपकी ज़िम्मेदारी है। फ़ॉर्म-फ़िल क्रेडिट सिर्फ़ सफल फ़िल पर लगता है, और फ़िल असफल होने पर वापस हो जाता है।",
	"You can always try the free watermarked download first, so you see exactly what you will get.": "आप पहले हमेशा मुफ़्त वॉटरमार्क वाला डाउनलोड आज़मा सकते हैं, ताकि आपको पता रहे कि आपको क्या मिलेगा।",
	"You can create a CV with plain or designed templates, download it as PDF or DOCX, and use your CV to fill job application forms.": "आप सादे या डिज़ाइन वाले टेम्पलेट से CV बना सकते हैं, PDF या DOCX में डाउनलोड कर सकते हैं, और अपने CV से नौकरी के फ़ॉर्म भर सकते हैं।",
	"You can delete your saved CV at any time by clearing your browser's site data for this website.": "आप कभी भी इस वेबसाइट का ब्राउज़र साइट डेटा साफ़ करके अपना सेव किया CV हटा सकते हैं।",
	"You can keep it or have it deleted — entirely your choice.": "आप इसे रख सकते हैं या हटवा सकते हैं — पूरी तरह आपकी पसंद।",
	"You have used today's free download. Try again tomorrow or pay ₹20.": "आज का मुफ़्त डाउनलोड इस्तेमाल हो चुका है। कल फिर कोशिश करें या ₹20 दें।",
	"You may ask to access, correct or erase your data, withdraw consent, nominate another person, and raise a grievance. Email us; if you are not satisfied with our response you may approach the Data Protection Board of India.": "पहुँच, सुधार, मिटाने, सहमति वापस लेने, नामांकन और शिकायत का अधिकार। हमें ईमेल करें; संतुष्ट न हों तो भारत के डेटा संरक्षण बोर्ड से संपर्क कर सकते हैं।",
	"You own what you write in your CV. You are responsible for making sure it is true and that you have the right to use it.": "आपके CV में लिखी चीज़ें आपकी हैं। यह सुनिश्चित करना आपकी ज़िम्मेदारी है कि वे सही हों और आपको उन्हें इस्तेमाल करने का अधिकार हो।",
	"You save": "आपकी बचत",
	"Your CV is saved in your own browser.": "आपका CV आपके अपने ब्राउज़र में सेव होता है।",
