	"Your CVs, drafts and plan key are stored only in this browser. You can withdraw consent and delete them at any time.": "आपके CV, ड्राफ़्ट और प्लान कुंजी सिर्फ़ इसी ब्राउज़र में रहते हैं। आप कभी भी सहमति वापस लेकर इन्हें हटा सकते हैं।",
