	"Withdraw consent and delete all FormZalo data saved in this browser (CVs, drafts, plan key, history)? This cannot be undone.": "सहमति वापस लें और इस ब्राउज़र में सेव सारा FormZalo डेटा (CV, ड्राफ़्ट, प्लान की, हिस्ट्री) हटाएँ? इसे वापस नहीं किया जा सकता।",
