	"Sample dossier loaded.": "सैंपल डॉसियर लोड हो गया।",
	"FormZalo (\"we\") is a CV builder and form-filling tool. Contact / Grievance Officer: {email} (we aim to reply within 2 working days).": "FormZalo (\"हम\") एक CV बिल्डर और फ़ॉर्म भरने का टूल है। संपर्क / शिकायत अधिकारी: {email} (हम 2 कार्य-दिवसों में जवाब देने का लक्ष्य रखते हैं)।",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). FormZalo has no interest in your data beyond this purpose.": "सिर्फ़ अपना CV बनाने और फ़ॉर्म भरने के लिए, और प्लान का इस्तेमाल गिनने के लिए। हम आपका डेटा नहीं बेचते और प्रोफ़ाइलिंग के लिए आपके CV डेटा का इस्तेमाल नहीं करते। विज्ञापन, अगर चालू हों, तो सिर्फ़ कंटेंट पेजों पर दिखते हैं और Google के विज्ञापन कुकीज़ इस्तेमाल कर सकते हैं (पूरी प्राइवेसी पॉलिसी देखें)। इस उद्देश्य से आगे FormZalo को आपके डेटा में कोई रुचि नहीं है।",
	"Note: FormZalo is currently in trial mode. No real payments are being taken yet.": "ध्यान दें: FormZalo अभी ट्रायल मोड में है। अभी कोई असली भुगतान नहीं लिया जा रहा है।",
	"What FormZalo does, support, and plans.": "FormZalo क्या करता है, सहायता और प्लान।",
	"1. What FormZalo does": "1. FormZalo क्या करता है",
	"FormZalo has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "FormZalo में कोई मासिक प्लान नहीं है; प्रति माह की रकम सिर्फ़ सालाना कीमत ÷ 12 है। बचत की तुलना उतना ही इस्तेमाल हमारी अपनी सिंगल-यूज़ कीमत पर एक-एक करके खरीदने से की गई है। Global Pro में 300 CV जनरेशन भी शामिल हैं, जो ऊपर की बचत में नहीं गिने गए।",
