	"FormZalo is currently in trial mode and is not taking real payments yet.": "FormZalo अभी ट्रायल मोड में है और अभी असली भुगतान नहीं ले रहा है।",
	"Many CV tools charge around $24–$50 per month on monthly plans. FormZalo has no monthly plan: we sell single uses and yearly plans.": "कई CV टूल मासिक प्लान पर लगभग $24–$50 प्रति माह लेते हैं। FormZalo में कोई मासिक प्लान नहीं है: हम सिंगल-यूज़ और सालाना प्लान बेचते हैं।",
	"Free to edit and preview — no sign-up needed.": "एडिट और प्रीव्यू मुफ़्त — साइन-अप ज़रूरी नहीं।",
