	"A CV (curriculum vitae) is a fuller record of your education, work, publications and achievements, and can be longer.": "CV(履歴書、curriculum vitae)は学歴、職歴、論文、実績をより詳しくまとめた記録で、長くなることもあります。",
	"A free CV builder: creating, editing, saving and choosing templates are all free, with no login needed.": "無料の CV 作成ツール:作成・編集・保存・テンプレート選択はすべて無料、ログイン不要です。",
	"A good cover letter is short, specific to the job and explains why you fit.": "良いカバーレターは短く、求人に合わせて具体的で、なぜ自分が適任かを説明します。",
	"A human expert checks your CV and suggests improvements.": "専門家が CV を確認し、改善点を提案します。",
	"A resume is a short summary (usually one or two pages) tailored to one job.": "レジュメは 1 つの求人に合わせた短い要約(通常 1〜2 ページ)です。",
