	"A step-by-step guide to a one-page CV when you have little or no work experience.": "職務経験が少ない、またはまったくない場合に 1 ページの CV を作る手順ガイド。",
	"A text-based PDF or a DOCX works with most systems. Scanned images do not.": "テキストベースの PDF や DOCX はほとんどのシステムで読めます。スキャン画像は読めません。",
