	Advertisement: "広告",
	"Advertising cookies: when ads are switched on, Google AdSense and its partners may use cookies or similar technologies to show and measure ads, including personalised ads where the law allows. You can opt out of personalised ads at adssettings.google.com. Visitors from the EEA, UK and Switzerland are asked for consent first.": "広告 Cookie:広告を有効にすると、Google AdSense とそのパートナーが広告の表示と測定のために Cookie や類似技術を使用することがあり、法律で認められる場合はパーソナライズ広告も含まれます。パーソナライズ広告は adssettings.google.com でオフにできます。EEA、英国、スイスからの訪問者には事前に同意を求めます。",
	"Affiliate links: some links on the page shown after a download are affiliate links marked as sponsored. If you use them, the partner may set its own cookies.": "アフィリエイトリンク:ダウンロード後に表示されるページの一部のリンクは、スポンサーと明記されたアフィリエイトリンクです。利用するとパートナーが独自の Cookie を設定する場合があります。",
