	"All guides": "すべてのガイド",
	"All templates are free to edit and preview. Each is shown with sample data; your own details replace it in the editor.": "すべてのテンプレートは無料で編集・プレビューできます。サンプルデータで表示しており、エディターではあなたの情報に置き換わります。",
	"Always save the confirmation page and payment receipt.": "確認ページと支払い領収書は必ず保存します。",
	"Anyone can create, edit, save and choose CV templates for free without logging in, and download a watermarked PDF/DOCX for free.": "誰でもログインなしで無料で CV を作成・編集・保存し、テンプレートを選び、透かし入りの PDF/DOCX をダウンロードできます。",
