	"CV Studio PDF and DOCX exports are text-based.": "CV Studio の PDF と DOCX の書き出しはテキストベースです。",
	"CV Studio has no interest in your data either way.": "CV Studio はいずれにしてもお客様のデータに関心はありません。",
	"CV Studio has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "CV Studio に月額プランはありません。月額表示は年額を12で割った目安です。節約額は、同じ利用量を当社の単発価格で1回ずつ購入した場合との比較です。Global Pro には CV 生成300回も含まれますが、上記の節約額には含めていません。",
