	"Follow the employer's instructions first. If none are given, a plain single-column layout is the safest choice for online portals, while a two-column layout reads well when a person opens the PDF.": "まず雇用主の指示に従います。指示がなければ、オンラインポータルにはシンプルな 1 段組みが最も安全で、人が PDF を開く場合は 2 段組みが読みやすくなります。",
	"Follow the job advertisement. If it says CV, send a CV; if it says resume, send a resume.": "求人広告に従います。CV とあれば CV を、レジュメとあればレジュメを送ります。",
	"Fonts are loaded from Google Fonts, so Google receives a normal request from your browser.": "フォントは Google Fonts から読み込まれるため、Google にはブラウザから通常のリクエストが送られます。",
