	"Good for online portals and applicant tracking systems that prefer a plain single column.": "シンプルな 1 段組みを好むオンラインポータルや応募者追跡システムに適しています。",
	"Good for private-sector jobs in India, the Gulf and abroad where a modern look helps.": "モダンな見た目が役立つ、インド・湾岸諸国・海外の民間企業の求人に適しています。",
	"Good for visa, embassy and government applications that expect a full personal record.": "完全な個人情報が求められるビザ、大使館、官公庁への申請に適しています。",
	"Group skills into technical (Excel, Python, AutoCAD) and languages (English, Hindi, Marathi).": "スキルを技術(Excel、Python、AutoCAD)と言語(英語、ヒンディー語、マラーティー語)に分けます。",
