	"I agree my details are shared with {biz} for form filling.": "フォーム入力のため、私の情報を {biz} と共有することに同意します。",
	"I have read this notice and agree to my data being stored for this purpose. I can withdraw at any time.": "このお知らせを読み、この目的のためにデータが保存されることに同意します。いつでも撤回できます。",
	Identity: "基本情報",
	"Identity, work, study, languages, and contact.": "基本情報、職歴、学歴、言語、連絡先。",
	"If a personal data breach occurs, we will inform affected users and the Data Protection Board of India without delay, and aim to do so within 72 hours of becoming aware of it.": "個人データの漏えいが発生した場合、影響を受けるユーザーとインドのデータ保護委員会に遅滞なく通知し、把握から72時間以内の通知を目指します。",
	"If it is too small, the portal may reject it as unclear. Do not over-compress.": "小さすぎると不鮮明として拒否されることがあります。圧縮しすぎないでください。",
	"If the file is too large, reduce the dimensions or the JPG quality.": "ファイルが大きすぎる場合は、寸法か JPG の画質を下げます。",
	"If this policy changes, we will update this page and its date.": "本ポリシーを変更した場合は、このページと日付を更新します。",
	"If you paid ₹20 and the PDF/DOCX does not generate, or the download fails because of a technical error on our side, you get a full refund.": "₹20 を支払ったのに PDF/DOCX が生成されない場合や、当社側の技術的エラーでダウンロードに失敗した場合は全額返金します。",
	"In CV Studio you can draw your signature or upload one; it is trimmed and saved as a PNG.": "CV Studio では署名を手書きで描くか、画像をアップロードできます。余白を切り取り PNG として保存します。",
	"In your browser's local storage on your own device. Clearing browser data or switching device can remove it, so download a copy.": "ご自身の端末のブラウザのローカルストレージです。ブラウザのデータ消去や端末の変更で消える場合があるため、コピーをダウンロードしてください。",
	"India: \"CV\" and \"resume\" are used interchangeably. Most private employers expect one or two pages.": "インド:「CV」と「レジュメ」は同じ意味で使われます。民間企業の多くは 1〜2 ページを想定しています。",
