	"It fills job application forms from your CV. A form-fill credit is used only when the fill succeeds, and is refunded if it fails. Always check the form before submitting.": "CV をもとに求人応募フォームを入力します。フォーム入力クレジットは成功時のみ使用され、失敗時は返却されます。送信前に必ずフォームを確認してください。",
	"It is needed only to fill your forms / build your CV.": "フォームの入力・CV の作成にのみ必要です。",
	"It never invents values. Anything missing is asked for and saved for next time.": "値を勝手に作ることはありません。足りない情報は質問し、次回のために保存します。",
