	"No active plan": "有効なプランはありません",
	"No ad is available right now. You can still pay ₹20 or download the free watermarked PDF.": "現在表示できる広告がありません。₹20 で解除するか、透かし入り PDF を無料でダウンロードできます。",
	"No applications yet. Use “Fill a form” to apply to a company.": "まだ応募はありません。「フォームを入力」から企業に応募できます。",
	"No client details yet. Share the link above.": "まだクライアントの情報はありません。上のリンクを共有してください。",
