	"No expiry date": "有効期限なし",
	"No job history yet? A clear one-page CV built around education, projects and skills still gets shortlisted.": "職歴がまだなくても、学歴・プロジェクト・スキルを軸にした分かりやすい 1 ページの CV なら書類選考を通過できます。",
	"No login is needed — you can use CV Studio as a guest.": "ログインは不要です — ゲストとして CV Studio を利用できます。",
