	Note: "注記",
	"Note the exact document specifications for photo, signature and certificates before you start.": "始める前に、写真・署名・証明書の正確な仕様を控えておきます。",
	"Note: CV Studio is currently in trial mode. No real payments are being taken yet.": "注意:CV Studio は現在試用モードです。まだ実際の支払いは受け付けていません。",
	Notes: "メモ",
	"Nothing from CV Studio is stored in this browser now. You can close this tab.": "このブラウザには CV Studio のデータは保存されていません。このタブを閉じても大丈夫です。",
	"Nothing recognizable was mapped. The extracted text is below if you want to copy from it.": "認識できる項目がありませんでした。抽出したテキストを下に表示しているので、必要に応じてコピーしてください。",
	"Nothing was collected and nothing is stored. You can close this page.": "何も収集・保存されていません。このページを閉じても大丈夫です。",
	Number: "番号",
	OK: "OK",
	Occupation: "職業",
	"Occupation / headline": "職業・肩書き",
	"Occupation or target role. Shown under your name.": "職業または希望職種。氏名の下に表示されます。",
	"Off: one general CV you can reuse for every application.": "オフ:どの応募にも使い回せる汎用 CV を1つ作成します。",
	Official: "公用",
	"On-device OCR": "端末内 OCR",
	"One international profile": "ひとつの国際プロフィール",
	"One point per line.": "1行に1項目。",
	"Online recruitment forms are strict. One wrong date or a mismatched name can get an application rejected.": "オンライン採用フォームは厳格です。日付が 1 つ違うだけ、名前が一致しないだけで不受理になることがあります。",
	"Only list skills you can discuss in an interview. Interviewers often test one at random.": "面接で説明できるスキルだけを書きます。面接官はよく無作為に 1 つを確かめます。",
	"Only the fields your form needs.": "フォームに必要な項目だけ。",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). CV Studio has no interest in your data beyond this purpose.": "CV の作成、フォームの入力、プランの利用回数の集計のためだけに使います。データの販売や CV データを使ったプロファイリングは行いません。広告を有効にした場合はコンテンツページにのみ表示され、Google の広告 Cookie が使われることがあります(詳しくはプライバシーポリシーをご覧ください)。CV Studio はこの目的以外であなたのデータに関心を持ちません。",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data, show ads, or use it for profiling. CV Studio has no interest in your data beyond this purpose.": "CV の作成とフォームの入力、プラン利用回数のカウントのためだけに使用します。データの販売、広告表示、プロファイリングは行いません。CV Studio はこの目的以外でお客様のデータに関心はありません。",
	"Open the desk": "デスクを開く",
	"Open the desk with your email": "メールでデスクを開く",
	"Open the downloaded file once and check names, dates and contact details.": "ダウンロードしたファイルを一度開き、名前・日付・連絡先を確認する。",
	"Open the file once to make sure it is the right image and not rotated.": "一度ファイルを開き、正しい画像で回転していないことを確認します。",
	"Opening the file…": "ファイルを開いています…",
	"Opening: the role you are applying for and where you saw it.": "書き出し:応募する職種と、求人をどこで見たか。",
	"Optional photo": "写真(任意)",
	"Optional. Germany and the Gulf often expect a photo; leave it off for the US, UK and Canada.": "任意。ドイツや湾岸諸国では写真を求められることが多いですが、米国・英国・カナダでは付けないでください。",
	"Optional. You can skip or close the ad. One free clean download per day. Paying ₹20 is always available.": "任意です。広告はスキップまたは閉じることができます。透かしなしのダウンロードは 1 日 1 回まで無料。₹20 でのロック解除はいつでも選べます。",
	"Or email {email} to request deletion.": "削除をご希望の場合は {email} までメールしてください。",
	"Or watch a short ad to download free": "または短い広告を見て無料でダウンロード",
	"Order {id}… · {plan} {price}. These buttons ask the server to simulate an outcome. Nothing is charged, and test unlocks never count as real purchases.": "注文 {id}… · {plan} {price}。これらのボタンはサーバーに結果のシミュレーションを依頼します。請求は発生せず、テスト解除が実際の購入として扱われることはありません。",
