	Advertisement: "إعلان",
	"Advertising cookies: when ads are switched on, Google AdSense and its partners may use cookies or similar technologies to show and measure ads, including personalised ads where the law allows. You can opt out of personalised ads at adssettings.google.com. Visitors from the EEA, UK and Switzerland are asked for consent first.": "ملفات تعريف الارتباط الإعلانية: عند تفعيل الإعلانات قد تستخدم Google AdSense وشركاؤها ملفات تعريف الارتباط أو تقنيات مشابهة لعرض الإعلانات وقياسها، بما في ذلك الإعلانات المخصصة حيث يسمح القانون. يمكنك إيقاف الإعلانات المخصصة من adssettings.google.com. يُطلب من زوار المنطقة الاقتصادية الأوروبية والمملكة المتحدة وسويسرا الموافقة أولًا.",
	"Affiliate links: some links on the page shown after a download are affiliate links marked as sponsored. If you use them, the partner may set its own cookies.": "روابط التسويق بالعمولة: بعض الروابط في الصفحة التي تظهر بعد التنزيل روابط تسويق بالعمولة موسومة بأنها برعاية. إذا استخدمتها فقد يضع الشريك ملفات تعريف الارتباط الخاصة به.",
	"After submission": "بعد الإرسال",
	"After you download your CV": "بعد تنزيل سيرتك الذاتية",
	"All guides": "كل الأدلة",
	"All templates are free to edit and preview. Each is shown with sample data; your own details replace it in the editor.": "جميع القوالب مجانية للتعديل والمعاينة. يُعرض كل قالب ببيانات نموذجية، وتحل بياناتك محلها في المحرر.",
	"Always save the confirmation page and payment receipt.": "احفظ دائمًا صفحة التأكيد وإيصال الدفع.",
	"Anyone can create, edit, save and choose CV templates for free without logging in, and download a watermarked PDF/DOCX for free.": "يمكن لأي شخص إنشاء السيرة الذاتية وتعديلها وحفظها واختيار القوالب مجانًا دون تسجيل دخول، وتنزيل ملف PDF/DOCX بعلامة مائية مجانًا.",
	"Anything else your CV or forms need. Add as many as you like.": "أي معلومات أخرى تحتاجها سيرتك الذاتية أو نماذجك. أضف ما تشاء.",
	"Apply to the form": "تطبيق على النموذج",
	"Approved refunds go back to your original payment method within 5–7 working days.": "تُعاد المبالغ المعتمدة إلى وسيلة الدفع الأصلية خلال 5–7 أيام عمل.",
	"Are payments live?": "هل المدفوعات مفعّلة؟",
	"Atlas résumé": "سيرة Atlas المختصرة",
	"Auto Form Filler: fills job application forms from your CV. A form-fill credit is used only when a fill succeeds, and is refunded if the fill fails.": "المُعبِّئ التلقائي للنماذج: يملأ نماذج طلبات التوظيف من سيرتك الذاتية. يُستخدم رصيد التعبئة فقط عند نجاحها، ويُعاد إذا فشلت.",
	"Available on request": "متاحة عند الطلب",
	"Avoid putting key information in images, text boxes or headers.": "تجنب وضع المعلومات الأساسية في صور أو مربعات نص أو رؤوس الصفحات.",
	B: "B",
