	"Blurred or cropped certificate scans.": "مسح ضوئي للشهادات غير واضح أو مقصوص.",
	"Both must be accurate, easy to scan and free of spelling mistakes.": "يجب أن يكون كلاهما دقيقًا وسهل القراءة وخاليًا من الأخطاء الإملائية.",
	"Both ads loaded — you can download your free preview now.": "تم تحميل الإعلانين — يمكنك الآن تنزيل المعاينة المجانية.",
	Brown: "بني",
	"Browse openings on a job portal that suit your profile.": "تصفّح الوظائف المناسبة لملفك على بوابة توظيف.",
	"Browse the CV templates gallery": "تصفّح معرض قوالب السيرة الذاتية",
	"Browser data: kept until you delete it (withdraw consent, or clear site data).": "بيانات المتصفح: تبقى حتى تحذفها (بسحب الموافقة أو مسح بيانات الموقع).",
	"Build new CV": "إنشاء سيرة ذاتية جديدة",
	"Build one profile, read an old CV or a photo of a form, and export a curriculum vitae, a compact résumé, or consular particulars.": "أنشئ ملفًا شخصيًا واحدًا، واقرأ سيرة ذاتية قديمة أو صورة نموذج، ثم صدِّر سيرة ذاتية كاملة أو مختصرة أو بيانات شخصية بصيغة قنصلية.",
	"Building…": "جارٍ الإنشاء…",
	"Business (Commercial) clients: details a client submits through a share link, the time of consent and submission.": "عملاء الأعمال (التجاريون): البيانات التي يرسلها العميل عبر رابط المشاركة، ووقت الموافقة والإرسال.",
	"By country": "حسب الدولة",
	"By using CV Studio you agree to these terms. If you do not agree, please do not use the service.": "باستخدامك CV Studio فإنك توافق على هذه الشروط. إن لم توافق، يُرجى عدم استخدام الخدمة.",
