	CV: "CV",
	"CV Generator": "مُنشئ السيرة الذاتية",
	"CV Studio": "CV Studio",
	"CV Studio (\"we\") is a CV builder and form-filling tool. Contact / Grievance Officer: {email} (we aim to reply within 2 working days).": "CV Studio (\"نحن\") أداة لإنشاء السير الذاتية وتعبئة النماذج. جهة الاتصال / مسؤول الشكاوى: {email} (نسعى للرد خلال يومي عمل).",
	"CV Studio PDF and DOCX exports are text-based.": "ملفات PDF وDOCX التي يصدّرها CV Studio نصية.",
	"CV Studio has no interest in your data either way.": "لا يهتم CV Studio ببياناتك في أي حال.",
	"CV Studio has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "لا توجد لدى CV Studio خطة شهرية؛ الرقم الشهري هو السعر السنوي مقسومًا على 12 فقط. يقارن التوفير بين الخطة السنوية وشراء الاستخدام نفسه مرة بمرة بسعرنا الفردي. تشمل Global Pro أيضًا 300 عملية إنشاء سيرة ذاتية، وهي غير محتسبة في التوفير أعلاه.",
	"CV Studio home": "الصفحة الرئيسية لـ CV Studio",
	"CV Studio is an online CV (resume) builder with an Auto Form Filler for job applications.": "CV Studio أداة إلكترونية لإنشاء السيرة الذاتية مع مُعبِّئ تلقائي لنماذج طلبات التوظيف.",
	"CV Studio is currently in trial mode and is not taking real payments yet.": "يعمل CV Studio حاليًا في الوضع التجريبي ولا يتقاضى مدفوعات حقيقية بعد.",
	"CV Studio is currently in trial mode and no real payments are taken yet.": "يعمل CV Studio حاليًا في الوضع التجريبي ولا تُؤخذ أي مدفوعات حقيقية بعد.",
	"CV Studio is currently in trial mode and no real payments are taken yet. Features and plans may change before full launch. Packages you have already bought keep the terms they were bought with.": "يعمل CV Studio حاليًا في الوضع التجريبي ولا تُؤخذ أي مدفوعات حقيقية بعد. قد تتغير الميزات والخطط قبل الإطلاق الكامل. تحتفظ الباقات التي اشتريتها بالشروط التي اشتُريت بها.",
	"CV Studio is currently in trial mode. No real payments are taken yet.": "يعمل CV Studio حاليًا في الوضع التجريبي. لا تُؤخذ أي مدفوعات حقيقية بعد.",
	"CV Studio lets you create, edit and save CVs, choose templates, download them as PDF or DOCX, and use an Auto Form Filler for job applications.": "يتيح لك CV Studio إنشاء السير الذاتية وتعديلها وحفظها، واختيار القوالب، وتنزيلها بصيغة PDF أو DOCX، واستخدام المُعبِّئ التلقائي لنماذج التوظيف.",
	"CV Studio · International desk": "CV Studio · المكتب الدولي",
