	"Clearing your browser data, or using a different browser or device, removes or hides that saved CV. Please keep your own copy (download it).": "مسح بيانات المتصفح أو استخدام متصفح أو جهاز آخر يحذف السيرة المحفوظة أو يخفيها. احتفظ بنسختك الخاصة (نزّلها).",
	"Click any line on the page to edit it. The form stays in step.": "انقر على أي سطر في الصفحة لتعديله. يبقى النموذج متزامنًا.",
	"Client details are auto-deleted after {days} days, or earlier on request.": "تُحذف بيانات العملاء تلقائيًا بعد {days} يومًا، أو قبل ذلك عند الطلب.",
	"Client submissions and plan records are stored on our server (hosted on Render). Encryption at rest of these records is planned as part of a database migration and is not yet complete.": "تُخزَّن بيانات العملاء وسجلات الخطط على خادمنا (المستضاف على Render). تشفير هذه السجلات أثناء التخزين مخطط له ضمن ترحيل قاعدة البيانات ولم يكتمل بعد.",
	"Client submissions: automatically deleted after {days} days, or earlier when the client or the business deletes them.": "بيانات العملاء: تُحذف تلقائيًا بعد {days} يومًا، أو قبل ذلك عندما يحذفها العميل أو الجهة التجارية.",
