	"Creating, editing, saving and choosing templates are free. The free download carries a watermark. Clean downloads and form fills use paid credits, as described on the Services & Plans page.": "الإنشاء والتعديل والحفظ واختيار القوالب مجانية. يحمل التنزيل المجاني علامة مائية. تستخدم التنزيلات النظيفة وتعبئة النماذج أرصدة مدفوعة، كما هو موضح في صفحة الخدمات والخطط.",
	"Crop tightly around the signature. Do not sign in capital letters if the notice forbids it.": "قصّ الصورة بإحكام حول التوقيع. لا توقّع بأحرف كبيرة إذا منع الإعلان ذلك.",
