	"Follow the employer's instructions first. If none are given, a plain single-column layout is the safest choice for online portals, while a two-column layout reads well when a person opens the PDF.": "اتبع تعليمات صاحب العمل أولًا. إن لم توجد، فالتخطيط البسيط بعمود واحد هو الأكثر أمانًا للبوابات الإلكترونية، بينما يُقرأ التخطيط بعمودين جيدًا عندما يفتح شخص ملف PDF.",
	"Follow the job advertisement. If it says CV, send a CV; if it says resume, send a resume.": "اتبع إعلان الوظيفة. إذا طلب CV فأرسل CV، وإذا طلب Resume فأرسل Resume.",
	"Fonts are loaded from Google Fonts, so Google receives a normal request from your browser.": "تُحمَّل الخطوط من Google Fonts، لذا تتلقى Google طلبًا عاديًا من متصفحك.",
