	"I have read this notice and agree to my data being stored for this purpose. I can withdraw at any time.": "قرأت هذا الإشعار وأوافق على تخزين بياناتي لهذا الغرض. يمكنني سحب موافقتي في أي وقت.",
	Identity: "الهوية",
	"Identity, work, study, languages, and contact.": "الهوية والعمل والدراسة واللغات والتواصل.",
	"If a personal data breach occurs, we will inform affected users and the Data Protection Board of India without delay, and aim to do so within 72 hours of becoming aware of it.": "في حال حدوث اختراق للبيانات الشخصية، سنُبلغ المستخدمين المتأثرين ومجلس حماية البيانات في الهند دون تأخير، ونسعى لذلك خلال 72 ساعة من علمنا به.",
	"If it is too small, the portal may reject it as unclear. Do not over-compress.": "إذا كان صغيرًا جدًا، فقد ترفضه البوابة لعدم وضوحه. لا تفرط في الضغط.",
	"If the file is too large, reduce the dimensions or the JPG quality.": "إذا كان الملف كبيرًا جدًا، فقلّل الأبعاد أو جودة JPG.",
	"If this policy changes, we will update this page and its date.": "إذا تغيّرت هذه السياسة، سنحدّث هذه الصفحة وتاريخها.",
	"If you paid ₹20 and the PDF/DOCX does not generate, or the download fails because of a technical error on our side, you get a full refund.": "إذا دفعت 20₹ ولم يُنشأ ملف PDF/DOCX، أو فشل التنزيل بسبب خطأ تقني من جهتنا، تسترد المبلغ كاملًا.",
	"In CV Studio you can draw your signature or upload one; it is trimmed and saved as a PNG.": "في CV Studio يمكنك رسم توقيعك أو رفعه؛ يُقصّ ويُحفظ بصيغة PNG.",
	"In your browser's local storage on your own device. Clearing browser data or switching device can remove it, so download a copy.": "في التخزين المحلي لمتصفحك على جهازك. قد يؤدي مسح بيانات المتصفح أو تغيير الجهاز إلى حذفها، لذا نزّل نسخة.",
	"India: \"CV\" and \"resume\" are used interchangeably. Most private employers expect one or two pages.": "الهند: تُستخدم كلمتا \"CV\" و\"Resume\" بالتبادل. معظم أصحاب العمل في القطاع الخاص يتوقعون صفحة أو صفحتين.",
