	"Many CV tools charge around $24–$50 per month on monthly plans. CV Studio has no monthly plan: we sell single uses and yearly plans.": "تفرض كثير من أدوات السيرة الذاتية نحو 24–50$ شهريًا في الخطط الشهرية. لا توجد لدى CV Studio خطة شهرية: نبيع استخدامات فردية وخططًا سنوية.",
	"Many companies run CVs through software before a person reads them. Simple formatting helps it read yours correctly.": "تمرّر شركات كثيرة السير الذاتية عبر برامج قبل أن يقرأها شخص. التنسيق البسيط يساعدها على قراءة سيرتك بشكل صحيح.",
