	"No expiry date": "بلا تاريخ انتهاء",
	"No job history yet? A clear one-page CV built around education, projects and skills still gets shortlisted.": "لا تملك سجلًا وظيفيًا بعد؟ السيرة الذاتية الواضحة من صفحة واحدة المبنية على التعليم والمشاريع والمهارات تصل إلى القائمة المختصرة أيضًا.",
	"No login is needed — you can use CV Studio as a guest.": "لا حاجة إلى تسجيل الدخول — يمكنك استخدام CV Studio كضيف.",
