	Note: "ملاحظة",
	"Note the exact document specifications for photo, signature and certificates before you start.": "دوّن المواصفات الدقيقة للصورة والتوقيع والشهادات قبل أن تبدأ.",
	"Note: CV Studio is currently in trial mode. No real payments are being taken yet.": "ملاحظة: يعمل CV Studio حاليًا في الوضع التجريبي. لا تُؤخذ أي مدفوعات حقيقية بعد.",
