	"One point per line.": "نقطة واحدة في كل سطر.",
	"Online recruitment forms are strict. One wrong date or a mismatched name can get an application rejected.": "استمارات التوظيف الإلكترونية صارمة. تاريخ خاطئ واحد أو اسم غير مطابق قد يؤدي إلى رفض الطلب.",
	"Only list skills you can discuss in an interview. Interviewers often test one at random.": "اذكر فقط المهارات التي تستطيع مناقشتها في المقابلة. كثيرًا ما يختبر المقابلون إحداها عشوائيًا.",
	"Only the fields your form needs.": "فقط الحقول التي يحتاجها نموذجك.",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). CV Studio has no interest in your data beyond this purpose.": "فقط لإنشاء سيرتك الذاتية وتعبئة استماراتك واحتساب استخدام الخطة. لا نبيع بياناتك ولا نستخدم بيانات سيرتك لإنشاء ملفات تعريفية. الإعلانات، إن فُعّلت، تظهر في صفحات المحتوى فقط وقد تستخدم ملفات تعريف الارتباط الإعلانية من Google (راجع سياسة الخصوصية الكاملة). لا يهتم CV Studio ببياناتك خارج هذا الغرض.",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data, show ads, or use it for profiling. CV Studio has no interest in your data beyond this purpose.": "فقط لإنشاء سيرتك الذاتية وتعبئة نماذجك واحتساب استخدام الخطة. لا نبيع بياناتك ولا نعرض إعلانات ولا نستخدمها للتنميط. لا يهتم CV Studio ببياناتك خارج هذا الغرض.",
	"Open the desk": "افتح المكتب",
	"Open the desk with your email": "افتح المكتب ببريدك الإلكتروني",
	"Open the downloaded file once and check names, dates and contact details.": "افتح الملف المنزّل مرة وتحقق من الأسماء والتواريخ وبيانات الاتصال.",
	"Open the file once to make sure it is the right image and not rotated.": "افتح الملف مرة للتأكد أنه الصورة الصحيحة وغير مقلوبة.",
	"Opening the file…": "جارٍ فتح الملف…",
	"Opening: the role you are applying for and where you saw it.": "الافتتاح: الوظيفة التي تتقدم إليها وأين رأيت إعلانها.",
	"Optional photo": "صورة اختيارية",
	"Optional. Germany and the Gulf often expect a photo; leave it off for the US, UK and Canada.": "اختياري. تطلب ألمانيا ودول الخليج الصورة غالبًا؛ لا تضفها للولايات المتحدة والمملكة المتحدة وكندا.",
	"Optional. You can skip or close the ad. One free clean download per day. Paying ₹20 is always available.": "اختياري. يمكنك تخطي الإعلان أو إغلاقه. تنزيل نظيف مجاني واحد يوميًا. خيار الدفع ₹20 متاح دائمًا.",
	"Or email {email} to request deletion.": "أو راسل {email} لطلب الحذف.",
	"Or watch a short ad to download free": "أو شاهد إعلانًا قصيرًا للتنزيل مجانًا",
	"Order {id}… · {plan} {price}. These buttons ask the server to simulate an outcome. Nothing is charged, and test unlocks never count as real purchases.": "الطلب {id}… · {plan} {price}. تطلب هذه الأزرار من الخادم محاكاة نتيجة. لا يُخصم أي مبلغ، ولا تُحتسب عمليات الفتح التجريبية مشتريات حقيقية أبدًا.",
	Ordinary: "عادي",
	Organization: "المنظمة",
	Other: "أخرى",
	"Other nationalities": "جنسيات أخرى",
	"Our hosting provider (Render) receives normal technical request data such as IP address and browser type.": "يتلقى مزود الاستضافة (Render) بيانات الطلب التقنية المعتادة مثل عنوان IP ونوع المتصفح.",
	"PDF and DOCX (Word).": "PDF وDOCX (Word).",
	"PDF text": "نص PDF",
	"PDF, photo, or image. The reader autofills the form on this device.": "PDF أو صورة. يملأ القارئ النموذج على هذا الجهاز.",
	"PIN code": "الرمز البريدي (PIN)",
	"Paid options remove the watermark and add form fills: Single Use ₹20 (India) or $1 (global) for one clean CV download or one form fill; Career Starter ₹1,000/year (2 profiles, 100 CV generations, 100 form fills); Global Pro $29/year (300 CV generations, 300 form fills).": "الخيارات المدفوعة تزيل العلامة المائية وتضيف تعبئة النماذج: Single Use بـ 20₹ (الهند) أو 1$ (عالميًا) لتنزيل سيرة نظيفة واحدة أو تعبئة نموذج واحدة؛ Career Starter بـ 1,000₹/سنة (ملفان، 100 إنشاء سيرة، 100 تعبئة نموذج)؛ Global Pro بـ 29$/سنة (300 إنشاء سيرة، 300 تعبئة نموذج).",
	"Paid: clean (no watermark) downloads and form fills with single-use credits or a yearly plan.": "مدفوع: تنزيلات نظيفة (بدون علامة مائية) وتعبئة نماذج بأرصدة فردية أو خطة سنوية.",
