	"Recruiters spend under a minute on a first screen. A fresher CV should fit on one A4 page.": "يقضي مسؤولو التوظيف أقل من دقيقة في الفرز الأول. يجب أن تتسع سيرة الخريج الجديد لصفحة A4 واحدة.",
