	"Schengen and visa forms ask for these options. Indian passports may also carry ECNR or ECR.": "تطلب نماذج شنغن والتأشيرات هذه الخيارات. قد يحمل جواز السفر الهندي أيضًا ECNR أو ECR.",
	"School / College / Board": "المدرسة / الكلية / المجلس",
	"Secure client details form": "نموذج آمن لبيانات العميل",
	"See the Refund Policy. In short: ₹20 single use is refunded if the download fails because of our technical error; yearly plans are refundable within 7 days if unused.": "راجع سياسة الاسترداد. باختصار: يُسترد مبلغ 20₹ إذا فشل التنزيل بسبب خطأ تقني من جهتنا؛ والخطط السنوية قابلة للاسترداد خلال 7 أيام إن لم تُستخدم.",
