	"The CV you type (name, contact details, experience, education, skills) is saved in your browser's local storage on your own device. It is not uploaded to us while you edit.": "السيرة التي تكتبها (الاسم، بيانات الاتصال، الخبرة، التعليم، المهارات) تُحفظ في التخزين المحلي لمتصفحك على جهازك، ولا تُرفع إلينا أثناء التعديل.",
	"The desk is empty. Read a document above, or fill the sample dossier to see a finished page.": "المكتب فارغ. اقرأ مستندًا أعلاه، أو املأ الملف النموذجي لترى صفحة مكتملة.",
	"The errors that most often get online applications rejected, and how to avoid them.": "الأخطاء التي تتسبب غالبًا في رفض الطلبات الإلكترونية، وكيف تتجنبها.",
	"The full CV with a watermark, so you can see exactly what you get before paying.": "السيرة الذاتية كاملة بعلامة مائية، لترى بالضبط ما ستحصل عليه قبل الدفع.",
