	"Online recruitment forms are strict. One wrong date or a mismatched name can get an application rejected.": "在线招聘表格要求严格。一个日期写错或姓名不一致，都可能导致申请被拒。",
	"Only list skills you can discuss in an interview. Interviewers often test one at random.": "只列出你能在面试中讲清楚的技能。面试官常会随机考察其中一项。",
	"Only the fields your form needs.": "只显示表格需要的字段。",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). CV Studio has no interest in your data beyond this purpose.": "仅用于制作你的简历、填写表格以及统计套餐使用次数。我们不出售你的数据，也不使用你的简历数据进行画像。广告(如开启)只出现在内容页面，并可能使用 Google 广告 Cookie(详见完整隐私政策)。除此之外，CV Studio 对你的数据没有任何兴趣。",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data, show ads, or use it for profiling. CV Studio has no interest in your data beyond this purpose.": "仅用于制作您的简历、填写您的表格以及统计套餐用量。我们不出售您的数据,不展示广告,也不用于用户画像。除此之外,CV Studio 对您的数据没有任何兴趣。",
