	"Open the downloaded file once and check names, dates and contact details.": "打开下载的文件，检查姓名、日期和联系方式。",
	"Open the file once to make sure it is the right image and not rotated.": "打开文件确认是正确的图片，且没有旋转。",
	"Opening the file…": "正在打开文件…",
	"Opening: the role you are applying for and where you saw it.": "开头:你申请的职位以及在哪里看到招聘信息。",
	"Optional photo": "可选照片",
	"Optional. Germany and the Gulf often expect a photo; leave it off for the US, UK and Canada.": "可选。德国和海湾国家通常要求照片;投递美国、英国和加拿大时请不要附照片。",
	"Optional. You can skip or close the ad. One free clean download per day. Paying ₹20 is always available.": "可选。你可以跳过或关闭广告。每天可免费下载一次无水印文件。随时可以选择支付 ₹20 解锁。",
	"Or email {email} to request deletion.": "或发邮件至 {email} 申请删除。",
