	"Order {id}… · {plan} {price}. These buttons ask the server to simulate an outcome. Nothing is charged, and test unlocks never count as real purchases.": "订单 {id}… · {plan} {price}。这些按钮会请服务器模拟一个结果。不会扣款，测试解锁也绝不会算作真实购买。",
