	"When you request a clean (paid) download or start a purchase, your CV content is sent to our server only to create the file and check the order. We keep order records (order ID, plan, amount, status, payment reference and a fingerprint/hash of the CV) — not the CV text itself.": "当您申请无水印(付费)下载或开始购买时,您的简历内容仅为生成文件和核对订单而发送到我们的服务器。我们保存订单记录(订单号、套餐、金额、状态、付款凭证及简历的指纹/哈希)——不保存简历正文本身。",
