	"Ads could not be shown — the free download is still available.": "No se pudieron mostrar los anuncios — la descarga gratuita sigue disponible.",
	Advertisement: "Publicidad",
	"Advertising cookies: when ads are switched on, Google AdSense and its partners may use cookies or similar technologies to show and measure ads, including personalised ads where the law allows. You can opt out of personalised ads at adssettings.google.com. Visitors from the EEA, UK and Switzerland are asked for consent first.": "Cookies publicitarias: cuando los anuncios están activados, Google AdSense y sus socios pueden usar cookies o tecnologías similares para mostrar y medir anuncios, incluidos anuncios personalizados cuando la ley lo permite. Puedes desactivar los anuncios personalizados en adssettings.google.com. A los visitantes del EEE, Reino Unido y Suiza se les pide consentimiento antes.",
	"Affiliate links: some links on the page shown after a download are affiliate links marked as sponsored. If you use them, the partner may set its own cookies.": "Enlaces de afiliado: algunos enlaces de la página que aparece tras una descarga son enlaces de afiliado marcados como patrocinados. Si los usas, el socio puede instalar sus propias cookies.",
	"After submission": "Después de enviar",
	"After you download your CV": "Después de descargar tu CV",
	"All guides": "Todas las guías",
	"All templates are free to edit and preview. Each is shown with sample data; your own details replace it in the editor.": "Todas las plantillas se pueden editar y previsualizar gratis. Cada una se muestra con datos de ejemplo; en el editor se sustituyen por los tuyos.",
	"Always save the confirmation page and payment receipt.": "Guarda siempre la página de confirmación y el justificante de pago.",
	"Anyone can create, edit, save and choose CV templates for free without logging in, and download a watermarked PDF/DOCX for free.": "Cualquiera puede crear, editar, guardar y elegir plantillas de CV gratis sin iniciar sesión, y descargar gratis un PDF/DOCX con marca de agua.",
	"Anything else your CV or forms need. Add as many as you like.": "Cualquier otro dato que necesiten tu CV o tus formularios. Añade tantos como quieras.",
	"Apply to the form": "Aplicar al formulario",
	"Approved refunds go back to your original payment method within 5–7 working days.": "Los reembolsos aprobados se devuelven a tu método de pago original en un plazo de 5 a 7 días hábiles.",
	"Are payments live?": "¿Ya se pueden hacer pagos reales?",
	"Atlas résumé": "Atlas résumé",
	"Auto Form Filler: fills job application forms from your CV. A form-fill credit is used only when a fill succeeds, and is refunded if the fill fails.": "Auto Form Filler: rellena formularios de candidatura a partir de tu CV. Solo se consume un crédito cuando el rellenado sale bien, y se devuelve si falla.",
	"Available on request": "Disponibles a petición",
