	"Building…": "Generando…",
	"Business (Commercial) clients: details a client submits through a share link, the time of consent and submission.": "Clientes empresariales: los datos que un cliente envía mediante un enlace compartido, y la fecha y hora del consentimiento y del envío.",
	"By country": "Por país",
	"By using CV Studio you agree to these terms. If you do not agree, please do not use the service.": "Al usar FormZalo aceptas estas condiciones. Si no estás de acuerdo, no utilices el servicio.",
