	"CV Studio": "FormZalo",
	"CV Studio (\"we\") is a CV builder and form-filling tool. Contact / Grievance Officer: {email} (we aim to reply within 2 working days).": "FormZalo («nosotros») es un creador de CV y una herramienta para rellenar formularios. Contacto / responsable de reclamaciones: {email} (intentamos responder en 2 días hábiles).",
	"CV Studio PDF and DOCX exports are text-based.": "Los PDF y DOCX que exporta FormZalo contienen texto real.",
	"CV Studio has no interest in your data either way.": "A FormZalo no le interesan tus datos en ningún caso.",
	"CV Studio has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "FormZalo no tiene plan mensual; la cifra mensual es solo el precio anual dividido entre 12. El ahorro compara el plan anual con comprar el mismo uso de uno en uno a nuestro precio de uso único. Global Pro incluye además 300 generaciones de CV, que no se cuentan en el ahorro anterior.",
	"CV Studio home": "Inicio de FormZalo",
	"CV Studio is an online CV (resume) builder with an Auto Form Filler for job applications.": "FormZalo es un creador de CV online con un Auto Form Filler para candidaturas de empleo.",
	"CV Studio is currently in trial mode and is not taking real payments yet.": "FormZalo está en modo de prueba y todavía no acepta pagos reales.",
	"CV Studio is currently in trial mode and no real payments are taken yet.": "FormZalo está en modo de prueba y todavía no se cobran pagos reales.",
	"CV Studio is currently in trial mode and no real payments are taken yet. Features and plans may change before full launch. Packages you have already bought keep the terms they were bought with.": "FormZalo está en modo de prueba y todavía no se cobran pagos reales. Las funciones y los planes pueden cambiar antes del lanzamiento definitivo. Los paquetes que ya hayas comprado mantienen las condiciones con las que los compraste.",
	"CV Studio is currently in trial mode. No real payments are taken yet.": "FormZalo está en modo de prueba. Todavía no se cobran pagos reales.",
	"CV Studio lets you create, edit and save CVs, choose templates, download them as PDF or DOCX, and use an Auto Form Filler for job applications.": "FormZalo te permite crear, editar y guardar CV, elegir plantillas, descargarlos en PDF o DOCX y usar un Auto Form Filler para candidaturas de empleo.",
