	"First name *": "Nombre *",
	"Follow the employer's instructions first. If none are given, a plain single-column layout is the safest choice for online portals, while a two-column layout reads well when a person opens the PDF.": "Sigue primero las instrucciones de la empresa. Si no hay ninguna, un diseño sencillo a una columna es lo más seguro para los portales online, mientras que uno a dos columnas se lee bien cuando una persona abre el PDF.",
	"Follow the job advertisement. If it says CV, send a CV; if it says resume, send a resume.": "Sigue la oferta de empleo. Si pide un CV, envía un CV; si pide un resume, envía un resume.",
