	"Identity, work, study, languages, and contact.": "Identidad, experiencia, estudios, idiomas y contacto.",
	"If a personal data breach occurs, we will inform affected users and the Data Protection Board of India without delay, and aim to do so within 72 hours of becoming aware of it.": "Si se produce una brecha de datos personales, informaremos sin demora a los usuarios afectados y a la Data Protection Board of India, e intentaremos hacerlo en un plazo de 72 horas desde que tengamos conocimiento de ella.",
	"If it is too small, the portal may reject it as unclear. Do not over-compress.": "Si es demasiado pequeña, el portal puede rechazarla por poco nítida. No la comprimas en exceso.",
	"If the file is too large, reduce the dimensions or the JPG quality.": "Si el archivo es demasiado grande, reduce las dimensiones o la calidad del JPG.",
	"If this policy changes, we will update this page and its date.": "Si esta política cambia, actualizaremos esta página y su fecha.",
	"If you paid ₹20 and the PDF/DOCX does not generate, or the download fails because of a technical error on our side, you get a full refund.": "Si pagaste ₹20 y el PDF/DOCX no se genera, o la descarga falla por un error técnico nuestro, te devolvemos el importe completo.",
	"In CV Studio you can draw your signature or upload one; it is trimmed and saved as a PNG.": "En FormZalo puedes dibujar tu firma o subirla; se recorta y se guarda como PNG.",
	"In your browser's local storage on your own device. Clearing browser data or switching device can remove it, so download a copy.": "En el almacenamiento local de tu navegador, en tu propio dispositivo. Si borras los datos del navegador o cambias de dispositivo, puede perderse, así que descarga una copia.",
	"India: \"CV\" and \"resume\" are used interchangeably. Most private employers expect one or two pages.": "India: «CV» y «resume» se usan indistintamente. La mayoría de empresas privadas esperan una o dos páginas.",
	Institution: "Centro",
