	"Issuing country": "País de expedición",
	"It fills job application forms from your CV. A form-fill credit is used only when the fill succeeds, and is refunded if it fails. Always check the form before submitting.": "Rellena formularios de candidatura a partir de tu CV. Solo se consume un crédito cuando el rellenado sale bien, y se devuelve si falla. Revisa siempre el formulario antes de enviarlo.",
	"It is needed only to fill your forms / build your CV.": "Solo se necesita para rellenar tus formularios / crear tu CV.",
	"It never invents values. Anything missing is asked for and saved for next time.": "Nunca inventa datos. Lo que falte se te pregunta y se guarda para la próxima vez.",
	"Jobs matching your CV": "Ofertas que encajan con tu CV",
