	Male: "Hombre",
	"Many CV tools charge around $24–$50 per month on monthly plans. CV Studio has no monthly plan: we sell single uses and yearly plans.": "Muchas herramientas de CV cobran entre 24 y 50 $ al mes en planes mensuales. FormZalo no tiene plan mensual: vendemos usos sueltos y planes anuales.",
	"Many companies run CVs through software before a person reads them. Simple formatting helps it read yours correctly.": "Muchas empresas pasan los CV por un software antes de que los lea una persona. Un formato sencillo ayuda a que lea bien el tuyo.",
