	"Scan your photo, signature and certificates in the required format and size.": "Escanea tu foto, firma y certificados con el formato y tamaño exigidos.",
	"Scanned PDF": "PDF escaneado",
	"Schengen and visa forms ask for these options. Indian passports may also carry ECNR or ECR.": "Los formularios Schengen y de visado piden estas opciones. Los pasaportes indios también pueden llevar ECNR o ECR.",
	"School / College / Board": "Colegio / Universidad / Organismo",
	"Secure client details form": "Formulario seguro de datos del cliente",
	"See the Refund Policy. In short: ₹20 single use is refunded if the download fails because of our technical error; yearly plans are refundable within 7 days if unused.": "Consulta la Política de reembolsos. En resumen: el uso único de ₹20 se reembolsa si la descarga falla por un error técnico nuestro; los planes anuales son reembolsables en 7 días si no se han usado.",
