	"₹20 one-time": "₹20 pago único",
	"← Back to CV Studio": "← Volver a FormZalo",
	"Choose a template": "Elige una plantilla",
	"Fill your Master Profile": "Rellena tu perfil maestro",
	"Download PDF or Word": "Descargar PDF o Word",
	"Free watermarked preview": "Vista previa gratuita con marca de agua",
	"No sign-up — guest mode": "Sin registro — modo invitado",
	"Your data stays in this browser": "Tus datos permanecen en este navegador",
	"FormZalo — Free CV generator & auto form filler": "FormZalo — Generador de CV gratuito y autorrelleno de formularios",
	"Build a professional CV from one Master Profile.": "Crea un CV profesional a partir de un único perfil maestro.",
	"Fill in your details once, choose a template, and download PDF or Word. Reuse the same profile to fill job application forms faster.": "Rellena tus datos una vez, elige una plantilla y descarga en PDF o Word. Reutiliza el mismo perfil para rellenar solicitudes de empleo más rápido.",
	"Start building your CV — free": "Empieza a crear tu CV — gratis",
	"Auto Form Filler is a paid-plan feature.": "El autorrelleno de formularios es una función de pago.",
	FormZalo: "FormZalo",
	"← Back to FormZalo": "← Volver a FormZalo",
	"Nothing from FormZalo is stored in this browser now. You can close this tab.": "Ya no se guarda nada de FormZalo en este navegador. Puedes cerrar esta pestaña.",
	"Withdraw consent and delete all FormZalo data saved in this browser (CVs, drafts, plan key, history)? This cannot be undone.": "¿Retirar el consentimiento y eliminar todos los datos de FormZalo guardados en este navegador (CV, borradores, clave del plan, historial)? Esto no se puede deshacer.",
	"Free CV generator and auto form filler": "Generador de CV gratuito y autorrelleno de formularios",
	"All rights reserved.": "Todos los derechos reservados.",
	"Loading your dashboard…": "Cargando tu panel…",
	"Everything you have created with FormZalo, saved in this browser.": "Todo lo que has creado con FormZalo, guardado en este navegador.",
	"Permanently delete this client's details from FormZalo?": "¿Eliminar permanentemente los datos de este cliente de FormZalo?",
	"FormZalo · International desk": "FormZalo · Mesa internacional",
	"CV headings": "Encabezados del CV",
	"Language of headings inside your CV": "Idioma de los encabezados de tu CV",
	"Free CV generator · auto form filler · international CV generator": "Generador de CV gratuito · autorrelleno de formularios · generador internacional de CV",
	"Sample dossier loaded.": "Expediente de ejemplo cargado.",
	"FormZalo (\"we\") is a CV builder and form-filling tool. Contact / Grievance Officer: {email} (we aim to reply within 2 working days).": "FormZalo («nosotros») es una herramienta para crear CV y rellenar formularios. Contacto / Responsable de reclamaciones: {email} (intentamos responder en 2 días laborables).",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). FormZalo has no interest in your data beyond this purpose.": "Solo para crear tu CV y rellenar tus formularios, y para contar el uso del plan. No vendemos tus datos ni usamos los datos de tu CV para crear perfiles. Los anuncios, si están activados, solo aparecen en las páginas de contenido y pueden usar cookies publicitarias de Google (consulta la política de privacidad completa). FormZalo no tiene ningún otro interés en tus datos.",
	"Note: FormZalo is currently in trial mode. No real payments are being taken yet.": "Nota: FormZalo está actualmente en modo de prueba. Todavía no se aceptan pagos reales.",
	"What FormZalo does, support, and plans.": "Qué hace FormZalo, soporte y planes.",
	"1. What FormZalo does": "1. Qué hace FormZalo",
	"FormZalo has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "FormZalo no tiene plan mensual; la cifra mensual es simplemente el precio anual dividido entre 12. El ahorro compara el plan anual con comprar el mismo uso de uno en uno a nuestro precio de uso único. Global Pro también incluye 300 generaciones de CV, que no se cuentan en el ahorro anterior.",
	"5. About FormZalo (for AI assistants and search)": "5. Acerca de FormZalo (para asistentes de IA y buscadores)",
	"FormZalo is an online CV (resume) builder with an Auto Form Filler for job applications.": "FormZalo es un creador de CV (currículum) en línea con autorrelleno de formularios para solicitudes de empleo.",
	"FormZalo is currently in trial mode and is not taking real payments yet.": "FormZalo está actualmente en modo de prueba y todavía no acepta pagos reales.",
