	"Fill in what you know. Empty answers are skipped, and nothing is guessed. Answers are saved to your profile for next time.": "Remplissez ce que vous savez. Les réponses vides sont ignorées et rien n’est deviné. Les réponses sont enregistrées dans votre profil pour la prochaine fois.",
