	"Fill the sample dossier": "Remplir le dossier d’exemple",
	"Filling government job application forms": "Remplir les formulaires de candidature dans la fonction publique",
	"Final checks": "Dernières vérifications",
	"First name *": "Prénom *",
	"Follow the employer's instructions first. If none are given, a plain single-column layout is the safest choice for online portals, while a two-column layout reads well when a person opens the PDF.": "Suivez d’abord les consignes de l’employeur. À défaut, une mise en page simple sur une colonne est le choix le plus sûr pour les plateformes en ligne, tandis qu’une mise en page sur deux colonnes se lit bien quand une personne ouvre le PDF.",
	"Follow the job advertisement. If it says CV, send a CV; if it says resume, send a resume.": "Suivez l’annonce. Si elle demande un CV, envoyez un CV ; si elle demande un resume, envoyez un resume.",
	"Fonts are loaded from Google Fonts, so Google receives a normal request from your browser.": "Les polices sont chargées depuis Google Fonts : Google reçoit donc une requête normale de votre navigateur.",
	"For a minor: name, phone, nationality.": "Pour un mineur : nom, téléphone, nationalité.",
	"For academic, research and medical posts, send the full CV with publications and training.": "Pour les postes universitaires, de recherche et médicaux, envoyez le CV complet avec publications et formations.",
