	Free: "Gratuit",
	"Free CV generator · auto form filler · international CB generator": "Générateur de CV gratuit · remplissage automatique de formulaires · générateur de CV international",
	"Free preview": "Aperçu gratuit",
	"Free watermarked download, so you can see exactly what you get before paying.": "Téléchargement gratuit avec filigrane, pour voir exactement ce que vous obtenez avant de payer.",
	"Free: create, edit, save and choose templates, with no login. Download a watermarked copy free.": "Gratuit : créez, modifiez, enregistrez et choisissez un modèle, sans connexion. Téléchargez gratuitement une copie avec filigrane.",
	From: "Du",
	"Full name": "Nom complet",
	"Full privacy policy": "Politique de confidentialité complète",
	"Full refund if you ask within 7 days of purchase and have not used the plan.": "Remboursement intégral si vous le demandez dans les 7 jours suivant l’achat et n’avez pas utilisé l’offre.",
