	"Global Pro": "Global Pro",
	"Global Single Use": "Global Single Use",
	"Good for online portals and applicant tracking systems that prefer a plain single column.": "Idéal pour les plateformes en ligne et les logiciels de recrutement qui préfèrent une seule colonne simple.",
	"Good for private-sector jobs in India, the Gulf and abroad where a modern look helps.": "Idéal pour les emplois du secteur privé en Inde, dans le Golfe et à l’étranger, où un style moderne est un atout.",
	"Good for visa, embassy and government applications that expect a full personal record.": "Idéal pour les demandes de visa, d’ambassade et d’administration qui attendent un état civil complet.",
	"Group skills into technical (Excel, Python, AutoCAD) and languages (English, Hindi, Marathi).": "Regroupez les compétences en techniques (Excel, Python, AutoCAD) et linguistiques (anglais, espagnol, allemand).",
