	Guides: "Guides",
	"Guides for your CV and job applications": "Guides pour votre CV et vos candidatures",
	"Gulf countries: employers often expect personal details such as nationality, visa status and sometimes a photo.": "Pays du Golfe : les employeurs attendent souvent des informations personnelles comme la nationalité, la situation de visa et parfois une photo.",
	"Hair colour": "Couleur des cheveux",
	Headings: "Titres",
