	"How CV Studio helps": "Comment FormZalo vous aide",
	"How applicant tracking systems read CVs and how to make sure yours is parsed correctly.": "Comment les logiciels de recrutement lisent les CV et comment vous assurer que le vôtre est bien interprété.",
	"How do I contact you?": "Comment vous contacter ?",
	"How do refunds work?": "Comment fonctionnent les remboursements ?",
	"How it works": "Comment ça marche",
	"How to choose": "Comment choisir",
	"How to prepare a passport-style photo and signature that portals accept.": "Comment préparer une photo d’identité et une signature acceptées par les plateformes.",
	"How to write a CV as a fresher": "Comment faire un CV quand on débute",
	"How to write a cover letter": "Comment rédiger une lettre de motivation",
	"I agree my details are shared with {biz} for form filling.": "J’accepte que mes informations soient partagées avec {biz} pour remplir des formulaires.",
	"I have read this notice and agree to my data being stored for this purpose. I can withdraw at any time.": "J’ai lu cet avis et j’accepte que mes données soient conservées à cette fin. Je peux retirer mon consentement à tout moment.",
	Identity: "Identité",
	"Identity, work, study, languages, and contact.": "Identité, expérience, études, langues et coordonnées.",
	"If a personal data breach occurs, we will inform affected users and the Data Protection Board of India without delay, and aim to do so within 72 hours of becoming aware of it.": "En cas de violation de données personnelles, nous en informerons sans délai les utilisateurs concernés et la Data Protection Board of India, en visant un délai de 72 heures après en avoir eu connaissance.",
	"If it is too small, the portal may reject it as unclear. Do not over-compress.": "Si elle est trop petite, la plateforme peut la refuser comme illisible. Ne compressez pas trop.",
	"If the file is too large, reduce the dimensions or the JPG quality.": "Si le fichier est trop lourd, réduisez les dimensions ou la qualité du JPG.",
	"If this policy changes, we will update this page and its date.": "Si cette politique change, nous mettrons à jour cette page et sa date.",
	"If you paid ₹20 and the PDF/DOCX does not generate, or the download fails because of a technical error on our side, you get a full refund.": "Si vous avez payé ₹20 et que le PDF/DOCX n’est pas généré, ou que le téléchargement échoue à cause d’une erreur technique de notre part, vous êtes intégralement remboursé.",
	"In CV Studio you can draw your signature or upload one; it is trimmed and saved as a PNG.": "Dans FormZalo, vous pouvez dessiner ou importer votre signature ; elle est recadrée et enregistrée au format PNG.",
	"In your browser's local storage on your own device. Clearing browser data or switching device can remove it, so download a copy.": "Dans le stockage local de votre navigateur, sur votre propre appareil. Effacer les données du navigateur ou changer d’appareil peut le supprimer : téléchargez donc une copie.",
	"India: \"CV\" and \"resume\" are used interchangeably. Most private employers expect one or two pages.": "Inde : « CV » et « resume » s’emploient indifféremment. La plupart des employeurs privés attendent une ou deux pages.",
