	"It fills job application forms from your CV. A form-fill credit is used only when the fill succeeds, and is refunded if it fails. Always check the form before submitting.": "Il remplit les formulaires de candidature à partir de votre CV. Un crédit n’est utilisé que si le remplissage réussit, et il est rendu en cas d’échec. Vérifiez toujours le formulaire avant de l’envoyer.",
	"It is needed only to fill your forms / build your CV.": "Uniquement nécessaire pour remplir vos formulaires / créer votre CV.",
	"It never invents values. Anything missing is asked for and saved for next time.": "Il n’invente jamais rien. Ce qui manque vous est demandé et enregistré pour la prochaine fois.",
