	"Many CV tools charge around $24–$50 per month on monthly plans. CV Studio has no monthly plan: we sell single uses and yearly plans.": "Beaucoup d’outils de CV facturent environ 24 à 50 $ par mois en abonnement mensuel. FormZalo n’a pas d’offre mensuelle : nous vendons des usages à l’unité et des offres annuelles.",
	"Many companies run CVs through software before a person reads them. Simple formatting helps it read yours correctly.": "Beaucoup d’entreprises font passer les CV par un logiciel avant qu’une personne les lise. Une mise en forme simple l’aide à lire le vôtre correctement.",
