	"See the Refund Policy. In short: ₹20 single use is refunded if the download fails because of our technical error; yearly plans are refundable within 7 days if unused.": "Consultez la Politique de remboursement. En bref : l’usage unique à ₹20 est remboursé si le téléchargement échoue à cause d’une erreur technique de notre part ; les offres annuelles sont remboursables sous 7 jours si elles n’ont pas été utilisées.",
