	"FormZalo (\"we\") is a CV builder and form-filling tool. Contact / Grievance Officer: {email} (we aim to reply within 2 working days).": "FormZalo (« nous ») est un outil de création de CV et de remplissage de formulaires. Contact / Responsable des réclamations : {email} (nous répondons en principe sous 2 jours ouvrés).",
	"Only to build your CV and fill your forms, and to count plan usage. We do not sell your data or use your CV data for profiling. Ads, if switched on, appear only on content pages and may use Google advertising cookies (see the full privacy policy). FormZalo has no interest in your data beyond this purpose.": "Uniquement pour créer votre CV et remplir vos formulaires, et pour compter l'utilisation du forfait. Nous ne vendons pas vos données et n'utilisons pas les données de votre CV pour du profilage. Les annonces, si elles sont activées, n'apparaissent que sur les pages de contenu et peuvent utiliser des cookies publicitaires Google (voir la politique de confidentialité complète). FormZalo n'a aucun autre intérêt pour vos données.",
	"Note: FormZalo is currently in trial mode. No real payments are being taken yet.": "Remarque : FormZalo est actuellement en mode d'essai. Aucun paiement réel n'est encore accepté.",
	"What FormZalo does, support, and plans.": "Ce que fait FormZalo, assistance et forfaits.",
	"1. What FormZalo does": "1. Ce que fait FormZalo",
	"FormZalo has no monthly plan; the per-month figure is just the yearly price divided by 12. Savings compare the yearly plan with buying the same usage one at a time at our own single-use price. Global Pro also includes 300 CV generations, which are not counted in the saving above.": "FormZalo n'a pas de forfait mensuel ; le montant mensuel est simplement le prix annuel divisé par 12. L'économie compare le forfait annuel à l'achat du même usage à l'unité à notre tarif à l'usage. Global Pro comprend aussi 300 générations de CV, qui ne sont pas comptées dans l'économie ci-dessus.",
	"5. About FormZalo (for AI assistants and search)": "5. À propos de FormZalo (pour les assistants IA et la recherche)",
	"FormZalo is an online CV (resume) builder with an Auto Form Filler for job applications.": "FormZalo est un créateur de CV en ligne avec remplissage automatique de formulaires pour les candidatures.",
	"FormZalo is currently in trial mode and is not taking real payments yet.": "FormZalo est actuellement en mode d'essai et n'accepte pas encore de paiements réels.",
	"Many CV tools charge around $24–$50 per month on monthly plans. FormZalo has no monthly plan: we sell single uses and yearly plans.": "De nombreux outils de CV facturent environ 24–50 $ par mois en forfait mensuel. FormZalo n'a pas de forfait mensuel : nous vendons des usages uniques et des forfaits annuels.",
	"Free to edit and preview — no sign-up needed.": "Gratuit à modifier et à prévisualiser — sans inscription.",
